package com.brainserve.onboarding.payments.infrastructure.persistence;
import com.brainserve.onboarding.payments.domain.model.Payment;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface PaymentRepository extends JpaRepository<Payment,UUID>{Optional<Payment> findByOrganizationIdAndId(UUID org,UUID id);Optional<Payment> findByOrganizationIdAndInvoiceIdAndSessionIdempotencyKey(UUID org,UUID invoiceId,String key);Optional<Payment> findByProviderAndProviderPaymentId(String provider,String providerPaymentId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from Payment p where p.organizationId=:org and p.id=:id")Optional<Payment> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);List<Payment> findAllByOrganizationIdAndInvoiceIdOrderByCreatedAtDescIdDesc(UUID org,UUID invoiceId);}
